    await this.collection('messages').insertOne(row,opts(session));await this.collection('conversations').updateOne({id:conversationId},{$set:{updatedAt:now}},opts(session));await this.collection('members').updateMany({conversationId,leftAt:null},{$set:{updatedAt:now}},opts(session));await this.collection('members').updateOne({conversationId,residentId:senderId},{$max:{readSeq:row.seq,deliveredSeq:row.seq,readAt:now,deliveredAt:now}},opts(session));
