  async publishTransferReceipt(senderId,conversationId,row){check(row.kind==='transfer'&&row.senderId===senderId&&row.conversationId===conversationId,'Transfer receipt is unavailable',400,'transfer_conversation_mismatch');const members=await this.fanoutMembers(conversationId,senderId);for await(const member of members)this.game.emitUser?.(member.residentId,'message',this.messageEvent(row));return{message:await this.messageView(row,senderId)};}
