  async delivered(id,conversationId){if(conversationId)return this.receipt(id,conversationId,false);const members=await this.collection('members').find({residentId:id,leftAt:null}).sort({updatedAt:-1}).limit(100).toArray();for(const m of members){try{await this.receipt(id,m.conversationId,false);}catch(e){if(e.status!==403)throw e;}}return{ok:true};}
