  async moderate(id,kind,target,enabled){await this.authenticate(id);identifier(target);check(['block','mute'].includes(kind)&&typeof enabled==='boolean','Invalid moderation control');check(target!==id,'Choose another resident');await this.authenticate(target);await this.transaction(async session=>{if(enabled)await this.collection('moderation').updateOne({owner:id,target,kind},{$setOnInsert:{createdAt:this.clock()}},{upsert:true,...opts(session)});else await this.collection('moderation').deleteOne({owner:id,target,kind},opts(session));if(kind==='block'&&enabled){await this.collection('friendships').deleteOne({pair:pair(id,target)},opts(session));await this.collection('follows').deleteMany({$or:[{owner:id,target},{owner:target,target:id}]},opts(session));await this.collection('home_visit_requests').updateMany({status:'pending',$or:[{ownerId:id,guestId:target},{ownerId:target,guestId:id}]},{$set:{status:'cancelled',answeredAt:this.clock()}},opts(session));const groups=this.collection('community_groups').find({ownerId:{$in:[id,target]}},{projection:{id:1,ownerId:1,conversationId:1},...opts(session)}).batchSize(50);for await(const group of groups){const revoked=group.ownerId===id?target:id;await this.collection('community_members').deleteOne({groupId:group.id,residentId:revoked},opts(session));await this.collection('members').updateOne({conversationId:group.conversationId,residentId:revoked,leftAt:null},{$set:{leftAt:this.clock()}},opts(session));}}});if(kind==='block'&&enabled){await this.reconcileVisits(id);await this.game.presence?.invalidatePair?.(id,target);}const rows=await this.collection('moderation').find({owner:id}).toArray();return{ok:true,blocked:rows.filter(r=>r.kind==='block').map(r=>r.target),muted:rows.filter(r=>r.kind==='mute').map(r=>r.target)};}
