  async postView(id,row){const blocked=await this.blockedIds(id),[resident,likes,liked,comments]=await Promise.all([this.resident(id,row.authorId),this.collection('social_likes').countDocuments({postId:row.id,residentId:{$nin:blocked}}),this.collection('social_likes').findOne({postId:row.id,residentId:id}),this.collection('social_comments').countDocuments({postId:row.id,authorId:{$nin:blocked}})]);return{id:row.id,userId:row.authorId,resident,text:row.text,imageDataUrl:row.imageDataUrl,kind:row.kind,createdAt:row.createdAt,expiresAt:row.expiresAt,likes,likedByMe:Boolean(liked),commentCount:comments};}
